const PINNED_NATIVE_SHA256 =
	"52b16658275b7848f8081a6542fee3448f1b1c5d3a36487107ae0e7cec95ac6f";
const SECRET_BYTES = 32;
const TOKEN_LENGTH = 43;
const MAX_CREDENTIAL_BYTES = 4_096;
const MAX_SECRET_BYTES = 8_192;
const MAX_STDIN_BYTES = 8_192;
const MAX_CHILD_OUTPUT_BYTES = 8_192;
