	/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const PAYLOAD_MAGIC = [0x53, 0x50, 0x43, 0x31] as const; // "SPC1"
const SCRIPT_PATH = fileURLToPath(
	new URL("./credential-vault.ts", import.meta.url),
);
const USAGE = `usage: bun run credential-vault.ts ${RUN_FLAG} --run-id <canonical-uuid> --deadline-ms <${MIN_DEADLINE_MS}..${MAX_DEADLINE_MS}>`;

